-- set value: 0 or 2^30 + bits
function PTLB_Has(t, v, id)
	if v < PTLB_FLAG then return nil end
	return PTLB_Bit(v, id - t.base)
end

function PTLB_With(t, v, id)
	if v < PTLB_FLAG then v = PTLB_FLAG end
	if PTLB_Has(t, v, id) then return v end
	return v + PTLB_Pow(id - t.base)
end

function PTLB_Without(t, v, id)
	if not PTLB_Has(t, v, id) then return v end
	v = v - PTLB_Pow(id - t.base)
	if v <= PTLB_FLAG then return 0 end
	return v
end

-- current PlayerIndex: store and send to the client (VNG s2c_synctaskvalue, read by PhongThanAutoFight.inl)
function PTLB_Apply(task, v)
	SetTask(task, v)
	SyncTaskValue(task)
end

-- number of learnt skills of the set, and of them the attack skills
function PTLB_Count(t, v)
	local n = 0
	local a = 0
	local i = 1
	while i <= t.n do
		local s = t[i]
		if PTLB_Has(t, v, s.id) and PTLB_Learnt(s.id) then
			n = n + 1
			if s.kind == 1 then a = a + 1 end
		end
		i = i + 1
	end
	return n, a
end

-- short text of the learnt skills of a Dao Si set: "Tho 3, Hoa 2, Bang 4 + buff 1"
function PTLB_DescDS(v)
	if v < PTLB_FLAG then return "theo ph\221m \174ang g\184n" end
	local c = { 0, 0, 0, 0 }
	local b = 0
	local i = 1
	while i <= PTLB_DS.n do
		local s = PTLB_DS[i]
		if PTLB_Has(PTLB_DS, v, s.id) and PTLB_Learnt(s.id) then
			if s.kind == 1 then c[s.el] = c[s.el] + 1 else b = b + 1 end
		end
		i = i + 1
	end
	local r = ""
	local k = { 4, 2, 1, 3 }
	i = 1
	while i <= 4 do
		if c[k[i]] > 0 then
			if r ~= "" then r = r .. ", " end
			r = r .. PTLB_EL[k[i]] .. " " .. c[k[i]]
		end
		i = i + 1
	end
	if r == "" then r = "ch\173a c\227 chi\170u \174\184nh \174\183 h\228c (d\239ng ph\221m)" end
	if b > 0 then r = r .. " + buff " .. b end
	return r
end

function PTLB_DescDN(v)
