-- learnt skills of the table, in table order: { [1] = index in the table, ... }
function PTLBDN_LearntList()
	PTLB_Load()
	local r = {}
	local i = 1
	while i <= PTLB_DN.n do
		if PTLB_Learnt(PTLB_DN[i].id) then tinsert(r, i) end
		i = i + 1
	end
	return r
end

function PTLBDN_Page(pg)
	PTLB_Load()
	local l = PTLBDN_LearntList()
	local v = GetTask(PTLB_T_DN)
	if getn(l) == 0 then
		Say("<color=yellow>L\214nh B\181i D\222 Nh\169n<color>: b\185n ch\173a h\228c chi\170u n\181o trong danh s\184ch.", 1, "\167\227ng/PTLB_No")
		return
	end
	local last = floor((getn(l) + 3) / 4)
	if pg > last then pg = last end
	local o = {}
	local n = 0
	local i = (pg - 1) * 4 + 1
	while i <= pg * 4 and l[i] do
		local s = PTLB_DN[l[i]]
		local m = "[ ] "
		if PTLB_Has(PTLB_DN, v, s.id) then m = "[x] " end
		local d = PTLB_KIND[s.kind]
		if s.kind == 1 then d = PTLB_EL[s.el] end
		n = n + 1
		o[n] = m .. s.nm .. " - " .. d .. "/PTLBDN_T" .. l[i]
		i = i + 1
	end
	if pg < last then n = n + 1 o[n] = "Trang sau " .. (pg + 1) .. "/PTLBDN_P" .. (pg + 1) end
	n = n + 1 o[n] = "Quay l\185i/PTLBDN_Main"
	n = n + 1 o[n] = "\167\227ng/PTLB_No"
	PTLB_Say(PTLBDN_Title() .. " (" .. "trang " .. pg .. "/" .. last .. ")", o)
end

function PTLBDN_P1() PTLBDN_Page(1) end
function PTLBDN_P2() PTLBDN_Page(2) end

-- toggle skill k of the table, then show the page that holds it
function PTLBDN_Toggle(k)
	PTLB_Load()
	local s = PTLB_DN[k]
	if not s or not PTLB_Learnt(s.id) then return end
	local v = GetTask(PTLB_T_DN)
	local on = nil
	if PTLB_Has(PTLB_DN, v, s.id) then v = PTLB_Without(PTLB_DN, v, s.id) else v = PTLB_With(PTLB_DN, v, s.id) on = 1 end
	-- nothing learnt left in the set: back to 0 (keys / off)
	local n, a = PTLB_Count(PTLB_DN, v)
	if n == 0 then v = 0 end
	PTLB_Apply(PTLB_T_DN, v)
	if on then Msg2Player("L\214nh B\181i D\222 Nh\169n: b\203t " .. s.nm) else Msg2Player("L\214nh B\181i D\222 Nh\169n: t\190t " .. s.nm) end
	local l = PTLBDN_LearntList()
	local pos = 1
	while l[pos] and l[pos] ~= k do pos = pos + 1 end
	PTLBDN_Page(floor((pos - 1) / 4) + 1)
end

function PTLBDN_T1() PTLBDN_Toggle(1) end
